calculate_factorial <- function(n_input) {
  if (n_input < 0) {
    stop("Factorial is not defined for negative numbers.")
  } else if (n_input == 0) {
    result_factorial <- 1
    return(result_factorial)
  } else {
    current_product <- 1
    i_counter <- 1
    while (i_counter <= n_input) {
      current_product <- current_product * i_counter
      i_counter <- i_counter + 1
    }
    final_factorial <- current_product
    return(final_factorial)
  }
}

