fibonacci_sequence <- function(n) {
  if (n <= 0) {
    return(numeric(0))
  } else if (n == 1) {
    result_vec <- c(0)
    return(result_vec)
  } else {
    fib_numbers <- numeric(n)
    fib_numbers[1] <- 0
    fib_numbers[2] <- 1

    i <- 3
    while (i <= n) {
      prev_val_1 <- fib_numbers[i - 1]
      prev_val_2 <- fib_numbers[i - 2]
      current_fib <- prev_val_1 + prev_val_2
      fib_numbers[i] <- current_fib
      i <- i + 1
    }
    final_output <- fib_numbers
    return(final_output)
  }
}

