round_to_integer <- function(numeric_vector_input) {
  rounded_vector <- vector("numeric", length(numeric_vector_input))

  for (i in seq_along(numeric_vector_input)) {
    current_number <- numeric_vector_input[i]

    # Check for half-integers and round to nearest even.
    # This is a common rounding convention (round half to even).
    fractional_part <- abs(current_number - floor(current_number))

    if (fractional_part == 0.5) {
      if (floor(current_number) %% 2 == 0) {
        rounded_value <- floor(current_number)
      } else {
        rounded_value <- ceiling(current_number)
      }
    } else {
      rounded_value <- round(current_number)
    }

    rounded_vector[i] <- rounded_value
  }

  final_result <- rounded_vector
  return(final_result)
}

