is_valid_email <- function(email_string) {

  has_at <- grepl("@", email_string)

  if (!has_at) {
    result <- FALSE
    return(result)
  }

  parts <- strsplit(email_string, "@")[[1]]

  if (length(parts) != 2) {
    result <- FALSE
    return(result)
  }

  domain_part <- parts[2]

  has_dot_in_domain <- grepl("\\.", domain_part)

  if (!has_dot_in_domain) {
    result <- FALSE
    return(result)
  }

  first_char_domain <- substr(domain_part, 1, 1)

  is_valid_start <- first_char_domain != "."

  last_char_domain <- substr(domain_part, nchar(domain_part), nchar(domain_part))

  is_valid_end <- last_char_domain != "."

  if (!is_valid_start || !is_valid_end) {
    result <- FALSE
    return(result)
  }

  no_double_dots <- !grepl("\\.\\.", domain_part)

  final_check <- has_at && has_dot_in_domain && is_valid_start && is_valid_end && no_double_dots

  result <- final_check

  return(result)
}

