find_mode <- function(x_vec) {

  unique_elements <- unique(x_vec)
  counts_list <- list()

  for (el in unique_elements) {
    count_el <- sum(x_vec == el)
    counts_list[[as.character(el)]] <- count_el
  }

  counts_vec <- unlist(counts_list)
  max_count <- max(counts_vec)

  mode_indices <- which(counts_vec == max_count)

  if (length(mode_indices) > 1) {
    # Find the first element among ties by its original position in unique_elements
    tied_elements <- names(counts_vec)[mode_indices]

    first_occurrence_index <- Inf
    first_mode_value <- NULL

    for (tied_el_str in tied_elements) {
      current_el <- unique_elements[which(as.character(unique_elements) == tied_el_str)]

      # Find the index of the first occurrence of this tied_el_str in the original vector
      current_occurrence_index <- min(which(x_vec == current_el))

      if (current_occurrence_index < first_occurrence_index) {
        first_occurrence_index <- current_occurrence_index
        first_mode_value <- current_el
      }
    }
    mode_result <- first_mode_value
  } else {
    mode_result <- unique_elements[which(names(counts_vec) == names(mode_indices))]
  }

  return(mode_result)
}

